  ('734', '[{"name":"Type","value":"TALISMAN"},{"name":"Cost","value":"3"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Hijos de Daana"},{"name":"Frequency","value":"CORTESANO"},{"name":"Number","value":"HD-122-236"},{"name":"Format","value":"Primer Bloque"},{"name":"Slug","value":"se-cae-el-cielo"},{"name":"Effect","value":"<p>Destruye un Aliado de raza Defensor. </p>"}]'::jsonb),
  ('608', '[{"name":"Type","value":"ORO"},{"name":"Cost","value":"0"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Helénica"},{"name":"Frequency","value":"ORO"},{"name":"Number","value":"IM-297-300"},{"name":"Format","value":"Primer Bloque"},{"name":"Slug","value":"aceite-de-oliva"},{"name":"Effect","value":"En tu Fase de Vigilia, si Aceite de Oliva está en tu reserva, puedes desterrarlo para buscar 1 Oro en tu Mazo Castillo y ponerlo en juego."}]'::jsonb),
