  ('9860', '[{"name":"Type","value":"ARMA"},{"name":"Cost","value":"1"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Productos Especiales"},{"name":"Frequency","value":"CORTESANO"},{"name":"Number","value":"IM-12-57"},{"name":"Format","value":"Furia Extendido"},{"name":"Slug","value":"garra-de-cristal"},{"name":"Effect","value":"Sólo puede ser portada por un Aliado Dragón. El portador gana 1 de Fuerza y no puede ser Destruido por Talismanes."}]'::jsonb),
