INSERT INTO _myl_ext VALUES
  ('2813', '[{"name":"Type","value":"ARMA"},{"name":"Cost","value":"2"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Espada Sagrada"},{"name":"Frequency","value":"VASALLO"},{"name":"Number","value":"AES-318-334"},{"name":"Format","value":"Primer Bloque"},{"name":"Slug","value":"espada-corta"},{"name":"Effect","value":"<p>Su portador gana + 1 a la fuerza y puede portar otra arma.</p>"}]'::jsonb),
