  ('9140', '[{"name":"Type","value":"TALISMAN"},{"name":"Cost","value":"3"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Furia"},{"name":"Frequency","value":"REAL"},{"name":"Number","value":"EF-24-90"},{"name":"Format","value":"Furia Extendido"},{"name":"Slug","value":"testudo"},{"name":"Effect","value":"Si todos tus Aliados son de la misma Raza, ganan 2 a la Fuerza hasta la Fase Final."}]'::jsonb),
