  ('4688', '[{"name":"Type","value":"TALISMAN"},{"name":"Cost","value":"3"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Espada Sagrada"},{"name":"Frequency","value":"REAL"},{"name":"Number","value":"CLESP-08"},{"name":"Format","value":"Primer Bloque"},{"name":"Slug","value":"desleal"},{"name":"Effect","value":"<p>Destierra un Aliado oponente.&nbsp;</p>"}]'::jsonb),
