  ('52313', '[{"name":"Type","value":"ORO"},{"name":"Cost","value":"0"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"AyD Vigilantes"},{"name":"Frequency","value":"PROMOCIONAL"},{"name":"Number","value":"AYDV-226"},{"name":"Format","value":"Imperio"},{"name":"Slug","value":"altar-de-moloch"},{"name":"Effect","value":"Cuando entra en juego, Roba una carta y tus Aliados no pueden salir del juego en Batalla Mitológica hasta tu próximo turno.<br />Una vez por turno, puedes pagar el coste de una carta oponente de la que seas dueño para subirla a tu mano y jugarla sin pagar su coste."}]'::jsonb),
  ('52284', '[{"name":"Type","value":"TOTEM"},{"name":"Cost","value":"1"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"AyD Vigilantes"},{"name":"Frequency","value":"VASALLO"},{"name":"Number","value":"AYDV-147"},{"name":"Format","value":"Imperio"},{"name":"Slug","value":"altar-del-juramento"},{"name":"Effect","value":"Cuando entra en juego, hasta dos Aliados ganan o pierden 2 a la Fuerza permanentemente.<br />Puedes Desterrarlo para subir del Cementerio a tu mano hasta dos cartas al azar."}]'::jsonb),
