  ('49618', '[{"name":"Type","value":"ORO"},{"name":"Cost","value":"0"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"La Venganza de Horus"},{"name":"Frequency","value":"PROMOCIONAL"},{"name":"Number","value":"HOR-298"},{"name":"Format","value":"Imperio"},{"name":"Slug","value":"sistro"},{"name":"Effect","value":"Cuando entra en juego, puedes pagar un Oro para convertir una carta de un Cementerio en un Oro sin habilidad y ponerlo en tu Oro Pagado.<br />Cancelar las habilidades de tus Oros cuesta un Oro adicional."}]'::jsonb),
  ('49356', '[{"name":"Type","value":"ALIADO"},{"name":"Cost","value":"0"},{"name":"Fuerza","value":"2"},{"name":"Race","value":"BESTIA"},{"name":"Edition","value":"La Venganza de Horus"},{"name":"Frequency","value":"REAL"},{"name":"Number","value":"HOR-036"},{"name":"Format","value":"Imperio"},{"name":"Slug","value":"sobek-ra"},{"name":"Effect","value":"Tu oponente no puede Barajar cartas en juego.<br />Puedes Desterrarlo de tu Cementerio para convertir la primera carta del Castillo oponente en un Aliado Bestia sin habilidad de Fuerza 2 y ponerlo en tu Línea de Defensa."}]'::jsonb),
