  ('44004', '[{"name":"Type","value":"ORO"},{"name":"Cost","value":"0"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Kemet"},{"name":"Frequency","value":"ORO"},{"name":"Number","value":"KEM-223"},{"name":"Format","value":"Imperio"},{"name":"Slug","value":"uraeus"}]'::jsonb),
