  ('44981', '[{"name":"Type","value":"TALISMAN"},{"name":"Cost","value":"2"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Kilimanjaro"},{"name":"Number","value":"KNJ-221"},{"name":"Format","value":"Imperio"},{"name":"Slug","value":"abosom"},{"name":"Effect","value":"Hasta la Fase Final, cuando un Aliado que controles sea Destruido, puedes poner ese Aliado en tu mano."}]'::jsonb),
