  ('50938', '[{"name":"Type","value":"TALISMAN"},{"name":"Cost","value":"2"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Lootbox 2024"},{"name":"Frequency","value":"PROMOCIONAL"},{"name":"Number","value":"LB24-025"},{"name":"Format","value":"Imperio"},{"name":"Slug","value":"beso-de-loto"},{"name":"Effect","value":"No puede ser Anulado.\r<br />Puedes Barajar una carta de tu mano para subirlo de tu Cementerio a tu mano.\r<br />Hasta dos cartas oponentes de coste 2 o menos pierden su habilidad y son Destruidas. Roba dos cartas."}]'::jsonb),
  ('50940', '[{"name":"Type","value":"ORO"},{"name":"Cost","value":"0"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Lootbox 2024"},{"name":"Frequency","value":"PROMOCIONAL"},{"name":"Number","value":"LB24-027"},{"name":"Format","value":"Imperio"},{"name":"Slug","value":"bifrost"},{"name":"Effect","value":"El primer Aliado o Tótem, de coste 2 o más, que juegues en tu turno no puede ser Anulado. Puedes pagarlo para buscar en tu Castillo una carta y jugarla por un Oro menos. Luego, convierte este Oro en un Oro sin habilidad y Roba dos cartas."}]'::jsonb),
  ('50916', '[{"name":"Type","value":"TOTEM"},{"name":"Cost","value":"1"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Lootbox 2024"},{"name":"Frequency","value":"PROMOCIONAL"},{"name":"Number","value":"LB24-003"},{"name":"Format","value":"Imperio"},{"name":"Slug","value":"ciudad-castillo"},{"name":"Effect","value":"No puede ser Barajado.\r<br />Cuando entra en juego, Roba dos cartas y Destierra hasta dos cartas de un Cementerio.\r<br />Los Aliados oponentes pierden tanta Fuerza como coste tengan."}]'::jsonb),
  ('50915', '[{"name":"Type","value":"TALISMAN"},{"name":"Cost","value":"0"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Lootbox 2024"},{"name":"Frequency","value":"PROMOCIONAL"},{"name":"Number","value":"LB24-002"},{"name":"Format","value":"Imperio"},{"name":"Slug","value":"encuentro"},{"name":"Effect","value":"Cuando lo juegues, puedes pagar cualquier cantidad de Oros y Destierra este Talismán. \r<br />Roba tantas cartas como Oros hayas pagado por este Talismán y los Aliados de coste igual o menor a ese número pierden su habilidad y son Barajados."}]'::jsonb),
