  ('51547', '[{"name":"Type","value":"ORO"},{"name":"Cost","value":"0"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Libertadores"},{"name":"Frequency","value":"PROMOCIONAL"},{"name":"Number","value":"LTD-194"},{"name":"Format","value":"Imperio"},{"name":"Slug","value":"salitre"},{"name":"Effect","value":"Cuando entra en juego, Roba dos cartas y Baraja una carta de tu mano.\r<br />Los Oros en juego son Indesterrables y puedes poner Oros en juego de tu Cementerio como si estuvieran en tu mano.\r<br />Cuando un Oro sea Destruído, Barájalo en el Castillo de su dueño."}]'::jsonb),
  ('42276', '[{"name":"Type","value":"TALISMAN"},{"name":"Cost","value":"2"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Sol Naciente"},{"name":"Number","value":"SN-086"},{"name":"Format","value":"Imperio"},{"name":"Slug","value":"noroi"},{"name":"Effect","value":"Para jugar este Talismán Destierra un Aliado de Raza Oni que controles. Destierra una carta en juego con coste igual o menor al Aliado Desterrado."}]'::jsonb),
