  ('52100', '[{"name":"Type","value":"ARMA"},{"name":"Cost","value":"1"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Imperio de Guerreros"},{"name":"Frequency","value":"ULTRA_REAL"},{"name":"Number","value":"MIG-035"},{"name":"Format","value":"Imperio"},{"name":"Slug","value":"espada-de-ohiggins"},{"name":"Effect","value":"Exhumar.\r<br />El portador gana 2 de Fuerza e Indesterrable.\r<br />En tu Vigilia, una vez por turno, puedes Barajar una carta que no sea Oro o buscar un Oro en tu Castillo y ponerlo en tu mano. En tu Fase Final, Destierra hasta tres cartas de los Cementerios y Roba dos cartas."}]'::jsonb),
  ('52071', '[{"name":"Type","value":"ARMA"},{"name":"Cost","value":"1"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Imperio de Guerreros"},{"name":"Frequency","value":"MEGA_REAL"},{"name":"Number","value":"MIG-006"},{"name":"Format","value":"Imperio"},{"name":"Slug","value":"espada-del-guerrero-inmortal"},{"name":"Effect","value":"El portador gana 2 de Fuerza y Furia.\r<br />En tu Vigilia, una vez por turno, puedes buscar un Aliado y un Arma en tu Castillo y ponerlos en tu mano o Robar dos cartas. Los Aliados que controlas ganan 1 de Fuerza."}]'::jsonb),
