  ('49831', '[{"name":"Type","value":"ORO"},{"name":"Cost","value":"0"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Napoleon"},{"name":"Frequency","value":"VASALLO"},{"name":"Number","value":"NAP-155"},{"name":"Format","value":"Imperio"},{"name":"Slug","value":"pistis-sophia"},{"name":"Effect","value":"Al comienzo de la Agrupación oponente, tus Aliados ganan 1 de Fuerza por el turno.\r<br />En la Fase Final oponente, si controlas dos o más Aliados, tu oponente Bota dos cartas."}]'::jsonb),
  ('49985', '[{"name":"Type","value":"ORO"},{"name":"Cost","value":"0"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Napoleon"},{"name":"Frequency","value":"VASALLO"},{"name":"Number","value":"NAP-309"},{"name":"Format","value":"Imperio"},{"name":"Slug","value":"pistis-sophia"},{"name":"Effect","value":"Al comienzo de la Agrupación oponente, tus Aliados ganan 1 de Fuerza por el turno.\r<br />En la Fase Final oponente, si controlas dos o más Aliados, tu oponente Bota dos cartas."}]'::jsonb),
