  ('10599', '[{"name":"Type","value":"TALISMAN"},{"name":"Cost","value":"1"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Productos Especiales"},{"name":"Frequency","value":"PROMOCIONAL"},{"name":"Number","value":"VIG - 08 P"},{"name":"Format","value":"Furia Extendido"},{"name":"Slug","value":"proteger-inocentes"},{"name":"Effect","value":"Hasta tres Aliados que controles son <b>Indestructibles</b> por el turno."}]'::jsonb),
