  ('9810', '[{"name":"Type","value":"TALISMAN"},{"name":"Cost","value":"2"},{"name":"Fuerza","value":"0"},{"name":"Edition","value":"Productos Especiales"},{"name":"Frequency","value":"PROMOCIONAL"},{"name":"Number","value":"WAS-09"},{"name":"Format","value":"Furia Extendido"},{"name":"Slug","value":"fuerza-de-lugh"},{"name":"Effect","value":"Destruye el Aliado oponente de mayor Fuerza. Si lo haces, Destierra o Baraja hasta dos cartas de un Cementerio."}]'::jsonb),
