-- Importa los bloques de Mitos y Leyendas (Primer Bloque, Furia Extendido, Primera Era, Imperio) desde los data.json.
-- Productos físicos = nombres de subcarpeta; enlaces carta <-> producto; extData con una entrada por valor (razas, mecánicas).
-- Une siempre por bloque + nombre. No borra cartas ni ediciones; solo elimina productos físicos que quedan sin ninguna carta.

SELECT setval(pg_get_serial_sequence('"TcgPhysicalProduct"', 'id'), GREATEST((SELECT COALESCE(MAX("id"), 0) FROM "TcgPhysicalProduct"), 1));

CREATE TEMP TABLE _myl_pp (block TEXT, name TEXT) ON COMMIT DROP;

SELECT 99, b."id", e.name
FROM _myl_pp e
JOIN "TcgBlock" b ON b."categoryId" = 99 AND b."name" = e.block
WHERE NOT EXISTS (SELECT 1 FROM "TcgPhysicalProduct" pp WHERE pp."categoryId" = 99 AND pp."blockId" = b."id" AND pp."name" = e.name);

CREATE TEMP TABLE _myl_link (pid TEXT, block TEXT, name TEXT, main BOOLEAN) ON COMMIT DROP;

-- Los enlaces de estos juegos se reemplazan por los del disco
DELETE FROM "TcgProductPhysicalProduct" l USING "TcgPhysicalProduct" pp WHERE pp."id" = l."physicalProductId" AND pp."categoryId" = 99;

CREATE TEMP TABLE _myl_resolved ON COMMIT DROP AS
SELECT k.pid, pp."id" AS ppid, k.main
FROM _myl_link k
JOIN "TcgBlock" b ON b."categoryId" = 99 AND b."name" = k.block
JOIN "TcgPhysicalProduct" pp ON pp."categoryId" = 99 AND pp."blockId" = b."id" AND pp."name" = k.name
JOIN "TcgProduct" pr ON pr."productId" = k.pid;

SELECT pid, ppid FROM _myl_resolved ON CONFLICT DO NOTHING;

UPDATE "TcgProduct" pr SET "physicalProductId" = r.ppid FROM _myl_resolved r WHERE r.pid = pr."productId" AND r.main;

CREATE TEMP TABLE _myl_ext (pid TEXT, ext JSONB) ON COMMIT DROP;

UPDATE "TcgProduct" pr SET "extData" = e.ext FROM _myl_ext e WHERE e.pid = pr."productId";

-- Productos físicos de estos juegos que no quedaron con ninguna carta ni son el principal de ninguna
DELETE FROM "TcgPhysicalProduct" pp WHERE pp."categoryId" = 99
  AND NOT EXISTS (SELECT 1 FROM "TcgProductPhysicalProduct" l WHERE l."physicalProductId" = pp."id")
  AND NOT EXISTS (SELECT 1 FROM "TcgProduct" pr WHERE pr."physicalProductId" = pp."id");
